8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * Apart from the one added prop described in the next paragraph, the differences from the base
14	 * file are the TypeScript annotations below, house formatting, and a small number of
15	 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
16	 * `Deviation from the base file` comment.
17	 *
18	 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
19	 * faithful port with the same `forwardRef` behaviour. It carries exactly one additive optional
20	 * prop over the base file's surface — `renderHeader`, documented on `ProductViewProps` below.
21	 * It is behaviour-preserving when omitted (its default renders the same private
22	 * `ProductViewHeader` the base file renders inline), and `renderHeader` has zero occurrences in
23	 * the base package, so none of the four base modules that import ProductView — product-view-modal
24	 * (index and bundle), bonus-product-view-modal, and pages/product-detail — passes it or is
25	 * affected by it. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see
26	 * the note at the foot of the file.)
27	 */
28	
29	import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
30	import { useLocation } from 'react-router-dom';
31	import { useIntl, FormattedMessage } from 'react-intl';
32	
33	import {
34	  Flex,
35	  Heading,
36	  Button,
37	  Skeleton,
38	  Box,
39	  Text,
40	  VStack,
41	  Fade,
42	  Stack,
43	  Radio,
44	  RadioGroup,
45	  useTheme,
46	} from '@salesforce/retail-react-app/app/components/shared/ui';
47	
48	// Constants
49	const DELIVERY_OPTIONS = {
50	  DELIVERY: 'delivery',
51	  PICKUP: 'pickup',
52	};
53	import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
54	import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
55	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
56	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
57	import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
58	import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
59	
60	// project components
61	import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
62	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
63	import Link from '@salesforce/retail-react-app/app/components/link';
64	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
65	import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
66	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
67	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
68	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
69	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
70	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
71	import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
72	import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
73	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
74	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
75	import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
76	import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
77	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
78	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
79	
80	/*
81	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
82	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
83	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
84	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
85	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
86	 *
87	 * Substituting them is a follow-up rather than part of this PR only because it also removes
88	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
89	 * across every commit.
90	 */
91	type SfccProduct = any;
92	type SfccVariant = any;
93	type SfccCategory = any;
94	type SfccPriceData = any;
95	
96	/** One selectable value of a variation attribute, as the base hooks shape it. */
97	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
98	
99	/** A variation attribute (colour, size, ...) with its selectable values. */
100	type SfccVariationAttribute = {
101	  id: string;
102	  name?: string;
103	  selectedValue?: SfccVariationValue;
104	  values: SfccVariationValue[];
105	};
106	
107	/** The per-child orderability record ProductView writes back to its parent. */
108	export type ChildProductOrderability = {
109	  showInventoryMessage?: boolean;
110	  unfulfillable?: boolean;
111	  isOutOfStock?: boolean;
112	  stockLevel?: number;
113	  productName?: string;
114	};
115	
116	export type ProductViewHeaderProps = {
117	  name?: string;
118	  currency?: string;
119	  priceData?: SfccPriceData;
120	  category?: SfccCategory[];
121	  product?: SfccProduct;
122	  isProductPartOfBundle?: boolean;
123	};
124	
125	/*
126	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
127	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
128	 * from the default implementation the base file supplies.
129	 */
130	type ProductViewProps = {
131	  product?: SfccProduct;
132	  category?: SfccCategory[];
133	  showFullLink?: boolean;
134	  imageSize?: 'sm' | 'md';
135	  isWishlistLoading?: boolean;
136	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
137	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
138	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
139	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
140	  isProductLoading?: boolean;
141	  isProductPartOfSet?: boolean;
142	  isProductPartOfBundle?: boolean;
143	  childOfBundleQuantity?: number;
144	  childProductOrderability?: Record<string, ChildProductOrderability>;
145	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
146	  isBasketLoading?: boolean;
147	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
148	  validateOrderability?: (
149	    variant: SfccVariant,
150	    product: SfccProduct,
151	    quantity: number,
152	    stockLevel: number,
153	  ) => boolean | undefined;
154	  showImageGallery?: boolean;
155	  setSelectedBundleQuantity?: (quantity: number) => void;
156	  selectedBundleParentQuantity?: number;
157	  pickupInStore?: boolean;
158	  setPickupInStore?: (checked: boolean) => void;
159	  onOpenStoreLocator?: () => void;
160	  showDeliveryOptions?: boolean;
161	  customButtons?: React.ReactElement[];
162	  promotionId?: string;
163	  maxOrderQuantity?: number | null;
164	  imageGalleryFooter?: React.ReactNode;
165	  alignItems?: string;
166	  controlledVariationValues?: Record<string, string> | null;
167	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
168	  /**
169	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
170	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
171	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
172	   * them. Defaults to rendering that same private header, so every existing caller — cart,
173	   * wishlist, bonus-product — is byte-identical unless it opts in.
174	   *
175	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
176	   * twice with the same arguments. Keep it pure.
177	   */
178	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
179	};
180	
181	/*
182	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
183	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
184	 * pages/product-detail).
185	 */
186	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
187	
188	/**
189	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
190	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
191	 * below. A consumer names it as the `this` parameter of its ref callback —
192	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
193	 * as written; no assertion is required at the prop site.
194	 */
195	export type ProductViewRefScope = {
196	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
197	};
198	
199	const ProductViewHeader = ({
200	  name,
201	  currency,
202	  priceData,
203	  category,
204	  product,
205	  isProductPartOfBundle,
206	}: ProductViewHeaderProps) => {
207	  return (
208	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
209	      {category && (
210	        <Skeleton isLoaded={category} minWidth={64}>
211	          <Breadcrumb categories={category} />
212	        </Skeleton>
213	      )}
214	
215	      {/* Title */}
216	      <Skeleton isLoaded={name}>
217	        <Heading fontSize="2xl">{`${name}`}</Heading>
218	      </Skeleton>
219	
220	      {!isProductPartOfBundle && (
221	        <>
222	          <Skeleton isLoaded={priceData?.currentPrice}>
223	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
224	          </Skeleton>
225	
226	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
227	        </>
228	      )}
229	    </VStack>
230	  );
231	};
232	
233	const ButtonWithRegistration = withRegistration(Button);
234	
235	/**
236	 * Render a product detail view that includes name, image gallery, price,
237	 * variant selections, action buttons
238	 */
239	
240	const ProductView = forwardRef(
241	  (
242	    {
243	      product,
244	      category,
245	      showFullLink = false,
246	      imageSize = 'md',
247	      isWishlistLoading = false,
248	      addToCart,
249	      updateCart,
250	      addToWishlist,
251	      updateWishlist,
252	      isProductLoading,
253	      isProductPartOfSet = false,
254	      isProductPartOfBundle = false,
255	      childOfBundleQuantity = 0,
256	      childProductOrderability,
257	      setChildProductOrderability,
258	      isBasketLoading = false,
259	      onVariantSelected = () => {},
260	      validateOrderability = (variant, product, quantity, stockLevel) => {
261	        if (isProductLoading) return false;
262	
263	        // If product has variations, a variant must be selected
264	        if (product?.variationAttributes?.length > 0 && !variant) {
265	          return false;
266	        }
267	
268	        // Check if product (either variant or standard) is orderable and if quantity is valid
269	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
270	      },
271	      showImageGallery = true,
272	      setSelectedBundleQuantity = () => {},
273	      selectedBundleParentQuantity = 1,
274	      pickupInStore = false,
275	      setPickupInStore = () => {},
276	      onOpenStoreLocator = () => {},
277	      showDeliveryOptions = true,
278	      customButtons = [],
279	      maxOrderQuantity = null,
280	      imageGalleryFooter = null,
281	      controlledVariationValues = null,
282	      onVariationChange = null,
283	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
284	    }: ProductViewProps,
285	    ref: ProductViewRef,
286	  ) => {
287	    const { currency: activeCurrency } = useCurrency();
288	    const showToast = useToast();
289	    const intl = useIntl();
290	    const location = useLocation();
291	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
292	    const {
293	      isOpen: isAddToCartModalOpen,
294	      onOpen: onAddToCartModalOpen,
295	      onClose: onAddToCartModalClose,
296	    } = useAddToCartModalContext();
297	
298	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
299	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
300	
301	    const theme = useTheme();
302	    const { confirmingBasket } = useSFPayments();
303	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
304	    const {
305	      showLoading,
306	      showInventoryMessage,
307	      inventoryMessage,
308	      quantity,
309	      minOrderQuantity,
310	      setQuantity,
311	      variant,
312	      variationParams,
313	      variationAttributes,
314	      stockLevel,
315	      stepQuantity,
316	      isOutOfStock,
317	      unfulfillable,
318	      isSelectedStoreOutOfStock,
319	      selectedStore,
320	    } = useDerivedProduct(
321	      product,
322	      isProductPartOfSet,
323	      isProductPartOfBundle,
324	      pickupInStore,
325	      controlledVariationValues,
326	      onVariationChange,
327	    );
328	    const priceData = useMemo(() => {
329	      return getPriceData(product, { quantity });
330	    }, [product, quantity]);
331	    const canAddToWishlist = !isProductLoading;
332	    const isProductASet = product?.type?.set;
333	    const isProductABundle = product?.type?.bundle;
334	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
335	    const [pickupEnabled, setPickupEnabled] = useState(false);
336	    const storeName = selectedStore?.name;
337	    const inventoryId = selectedStore?.inventoryId;
338	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
339	
340	    const { disableButton, customInventoryMessage } = useMemo(() => {
341	      let shouldDisableButton = showInventoryMessage;
342	      let currentInventoryMsg = '';
343	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
344	        // if any of the children are not orderable, it will disable the add to cart button
345	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
346	          return childProductOrderability[key].showInventoryMessage;
347	        });
348	        shouldDisableButton = !!unavailableChildProductKey;
349	        if (unavailableChildProductKey) {
350	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
351	          if (unavailableChildProduct.unfulfillable) {
352	            currentInventoryMsg = intl.formatMessage(
353	              {
354	                defaultMessage: 'Only {stockLevel} left for {productName}!',
355	                id: 'use_product.message.inventory_remaining_for_product',
356	              },
357	              {
358	                stockLevel: unavailableChildProduct.stockLevel,
359	                productName: unavailableChildProduct.productName,
360	              },
361	            );
362	          }
363	          if (unavailableChildProduct.isOutOfStock) {
364	            currentInventoryMsg = intl.formatMessage(
365	              {
366	                defaultMessage: 'Out of stock for {productName}',
367	                id: 'use_product.message.out_of_stock_for_product',
368	              },
369	              { productName: unavailableChildProduct.productName },
370	            );
371	          }
372	        }
373	      }
374	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
375	    }, [showInventoryMessage, childProductOrderability]);
376	
377	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
378	      const { scrollErrorIntoView = true } = opts;
379	      // Validate that all attributes are selected before proceeding.
380	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
381	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
382	      const scrollToError = showError && scrollErrorIntoView;
383	
384	      toggleShowOptionsMessage(showError);
385	
386	      if (scrollToError) {
387	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
388	        // while guarding it in `prepareBasket` below; the two only differ if the error
389	        // container has not mounted, where the base throws.
390	        errorContainerRef.current?.scrollIntoView({
391	          behavior: 'smooth',
392	          block: 'center',
393	        });
394	      }
395	
396	      return hasValidSelection;
397	    };
398	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
399	
400	    // prepareBasket is used to prepare the basket for express payments
401	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
402	    const prepareBasket = useCallback(async () => {
403	      // Validate that all attributes are selected before proceeding
404	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
405	      let errorMessage = '';
406	
407	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
408	        toggleShowOptionsMessage(true);
409	        if (errorContainerRef.current) {
410	          errorContainerRef.current.scrollIntoView({
411	            behavior: 'smooth',
412	            block: 'center',
413	          });
414	        }
415	        errorMessage = intl.formatMessage({
416	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
417	          id: 'product_view.prepareBasket',
418	        });
419	
420	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
421	        error.isValidationError = true;
422	        throw error;
423	      }
424	
425	      // Clean up temporary baskets before creating a new one
426	      await cleanupTemporaryBaskets();
427	
428	      // Create a new temporary basket
429	      const newBasket = await createBasket({
430	        parameters: {
431	          temporary: true,
432	        },
433	        body: {},
434	      });
435	
436	      const selectedProduct = variant || product;
437	      // Use variant's productId if variant is selected, otherwise use product's id
438	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
439	
440	      if (!productIdToUse) {
441	        errorMessage = intl.formatMessage({
442	          defaultMessage: 'Unable to determine product ID for basket',
443	          id: 'product_view.prepareBasket',
444	        });
445	        throw new Error(errorMessage);
446	      }
447	      // Add the product to the temporary basket
448	      const basketWithItem = await addItemToBasket({
449	        // SDK param widening — `newBasket` is the basket just created above.
450	        parameters: { basketId: newBasket.basketId as string },
451	        body: [
452	          {
453	            productId: productIdToUse,
454	            quantity: quantity,
455	          },
456	        ],
457	      });
458	
459	      return basketWithItem;
460	    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);
461	
462	    const renderActionButtons = () => {
463	      const buttons = [];
464	      const buttonText = {
465	        update: intl.formatMessage({
466	          defaultMessage: 'Update',
467	          id: 'product_view.button.update',
468	        }),
469	        addToCart: intl.formatMessage({
470	          defaultMessage: 'Add to Cart',
471	          id: 'product_view.button.add_to_cart',
472	        }),
473	        addSetToCart: intl.formatMessage({
474	          defaultMessage: 'Add Set to Cart',
475	          id: 'product_view.button.add_set_to_cart',
476	        }),
477	        addBundleToCart: intl.formatMessage({
478	          defaultMessage: 'Add Bundle to Cart',
479	          id: 'product_view.button.add_bundle_to_cart',
480	        }),
481	        addToWishlist: intl.formatMessage({
482	          defaultMessage: 'Add to Wishlist',
483	          id: 'product_view.button.add_to_wishlist',
484	        }),
485	        addSetToWishlist: intl.formatMessage({
486	          defaultMessage: 'Add Set to Wishlist',
487	          id: 'product_view.button.add_set_to_wishlist',
488	        }),
489	        addBundleToWishlist: intl.formatMessage({
490	          defaultMessage: 'Add Bundle to Wishlist',
491	          id: 'product_view.button.add_bundle_to_wishlist',
492	        }),
493	      };
494	
495	      const showError = () => {
496	        showToast({
497	          title: intl.formatMessage(API_ERROR_MESSAGE),
498	          status: 'error',
499	        });
500	      };
501	
502	      const handleCartItem = async () => {
503	        const hasValidSelection = validateAndShowError();
504	
505	        if (!hasValidSelection) {
506	          return null;
507	        }
508	
509	        if (!addToCart && !updateCart) return null;
510	        if (updateCart) {
511	          await updateCart(variant || product, quantity);
512	          return;
513	        }
514	        try {
515	          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
516	          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
517	          // those two statements.
518	          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
519	          // Open modal only when `addToCart` returns some data
520	          // It's possible that the item has been added to cart, but we don't want to open the modal.
521	          // See wishlist_primary_action for example.
522	          if (itemsAdded) {
523	            onAddToCartModalOpen({
524	              product,
525	              itemsAdded,
526	              selectedQuantity: quantity,
527	            });
528	          }
529	        } catch (e) {
530	          showError();
531	        }
532	      };
533	
534	      const handleWishlistItem = async () => {
535	        if (!updateWishlist && !addToWishlist) return null;
536	        if (updateWishlist) {
537	          updateWishlist(product, variant, quantity);
538	          return;
539	        }
540	        // Guarded above, exactly as `addToCart` is in handleCartItem.
541	        addToWishlist!(product, variant, quantity);
542	      };
543	
544	      // child product of bundles do not have add to cart button
545	      if ((addToCart || updateCart) && !isProductPartOfBundle) {
546	        buttons.push(
547	          <Button
548	            key="cart-button"
549	            onClick={handleCartItem}
550	            isDisabled={disableButton}
551	            isLoading={isBasketLoading}
552	            width="100%"
553	            variant="solid"
554	            marginBottom={4}
555	          >
556	            {updateCart
557	              ? buttonText.update
558	              : isProductASet
559	              ? buttonText.addSetToCart
560	              : isProductABundle
561	              ? buttonText.addBundleToCart
562	              : buttonText.addToCart}
563	          </Button>,
564	        );
565	      }
566	
567	      // child product of bundles do not have add to wishlist button
568	      if ((addToWishlist || updateWishlist) && !isProductPartOfBundle) {
569	        buttons.push(
570	          <ButtonWithRegistration
571	            key="wishlist-button"
572	            onClick={handleWishlistItem}
573	            disabled={isWishlistLoading || !canAddToWishlist}
574	            isLoading={isWishlistLoading}
575	            width="100%"
576	            variant="outline"
577	            marginBottom={4}
578	          >
579	            {updateWishlist
580	              ? buttonText.update
581	              : isProductASet
582	              ? buttonText.addSetToWishlist
583	              : isProductABundle
584	              ? buttonText.addBundleToWishlist
585	              : buttonText.addToWishlist}
586	          </ButtonWithRegistration>,
587	        );
588	      }
589	
590	      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
