826	            <Box display={['none', 'none', 'none', 'block']}>
827	              {renderHeader({
828	                name: product?.name,
829	                product,
830	                priceData,
831	                currency: product?.currency || activeCurrency,
832	                category,
833	                isProductPartOfBundle,
834	              })}
835	            </Box>
836	            <VStack align="stretch" spacing={4}>
837	              {isProductPartOfBundle && (
838	                <Box>
839	                  <Text fontWeight="medium" fontSize="md" aria-label="price">
840	                    <label>
841	                      {intl.formatMessage({
842	                        defaultMessage: 'Quantity',
843	                        id: 'product_view.label.quantity',
844	                      })}
845	                      : {childOfBundleQuantity}
846	                    </label>
847	                  </Text>
848	                </Box>
849	              )}
850	              {/*
851	                                Customize the skeletons shown for attributes to suit your needs. At the point
852	                                that we show the skeleton we do not know how many variations are selectable. So choose
853	                                a a skeleton that will meet most of your needs.
854	                            */}
855	              {showLoading ? (
856	                <>
857	                  {/* First Attribute Skeleton */}
858	                  <Skeleton height={6} width={32} />
859	                  <Skeleton height={20} width={64} />
860	
861	                  {/* Second Attribute Skeleton */}
862	                  <Skeleton height={6} width={32} />
863	                  <Skeleton height={20} width={64} />
864	                </>
865	              ) : (
866	                variationAttributes.map((attr: SfccVariationAttribute) => (
867	                  <React.Fragment key={attr.id}>
868	                    {renderVariationAttribute?.(attr) ?? renderDefaultVariationAttribute(attr)}
869	                  </React.Fragment>
870	                ))
871	              )}
872	
873	              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
874	              {!isProductASet && !isProductPartOfBundle && (
875	                <VStack align="stretch" maxWidth={'200px'}>
876	                  <Box fontWeight="bold">
877	                    <label htmlFor="quantity">
878	                      {intl.formatMessage({
879	                        defaultMessage: 'Quantity:',
880	                        id: 'product_view.label.quantity',
881	                      })}
882	                    </label>
883	                  </Box>
884	
885	                  <QuantityPicker
886	                    id="quantity"
887	                    step={stepQuantity}
888	                    value={quantity}
889	                    min={minOrderQuantity}
890	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
891	                    onChange={(stringValue: string, numberValue: number) => {
892	                      // Set the Quantity of product to value of input if value number
893	                      if (numberValue >= 0) {
894	                        setQuantity(numberValue);
895	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
896	                      } else if (stringValue === '') {
897	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
898	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
899	                        setQuantity(stringValue);
900	                      }
901	                    }}
902	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
903	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
904	                      const value = e.target.value;
905	                      if (parseInt(value) < 0 || value === '') {
906	                        setQuantity(minOrderQuantity);
907	                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
908	                      }
909	                    }}
910	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
911	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
912	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
913	                      // component, potentially as a prop called `selectInputOnFocus`.
914	                      e.target.select();
915	                    }}
916	                    productName={product?.name}
917	                  />
918	                </VStack>
919	              )}
920	              <Box ref={errorContainerRef}>
921	                {!showLoading && showOptionsMessage && (
922	                  <Fade in={true}>
923	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
924	                      {intl.formatMessage({
925	                        defaultMessage: 'Please select all your options above',
926	                      })}
927	                    </Text>
928	                  </Fade>
929	                )}
930	              </Box>
931	              <HideOnDesktop>
932	                {showFullLink && product && (
933	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
934	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
935	                  </Link>
936	                )}
937	              </HideOnDesktop>
938	              {isProductASet && <p>{product?.shortDescription}</p>}
939	            </VStack>
940	
941	            <Box>
942	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
943	                <Fade in={true}>
944	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
945	                    {inventoryMessage}
946	                  </Text>
947	                </Fade>
948	              )}
949	              {!showLoading && customInventoryMessage && (
950	                <Fade in={true}>
951	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
952	                    {customInventoryMessage}
953	                  </Text>
954	                </Fade>
955	              )}
956	              <Box>
957	                {showDeliveryOptions && (
958	                  <>
959	                    <Box mb={4}>
960	                      <Text fontWeight={600} mb={3}>
961	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
962	                      </Text>
963	                      <RadioGroup
964	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
965	                        onChange={handleDeliveryOptionChange}
966	                        mb={1}
967	                      >
968	                        <Stack direction="column" spacing={2}>
969	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
970	                            <FormattedMessage
971	                              defaultMessage="Ship to Address"
972	                              id="product_view.label.ship_to_address"
973	                            />
974	                          </Radio>
975	                          {storeLocatorEnabled && (
976	                            <Radio
977	                              value={DELIVERY_OPTIONS.PICKUP}
978	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
979	                            >
980	                              <FormattedMessage
981	                                defaultMessage="Pick Up in Store"
982	                                id="product_view.label.pickup_in_store"
983	                              />
984	                            </Radio>
985	                          )}
986	                        </Stack>
987	                      </RadioGroup>
988	                    </Box>
989	
990	                    {storeLocatorEnabled && (
991	                      <>
992	                        {storeName && inventoryId && (
993	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
994	                            {!isSelectedStoreOutOfStock
995	                              ? intl.formatMessage(
996	                                  {
997	                                    id: 'product_view.status.in_stock_at_store',
998	                                    defaultMessage: 'In stock at {storeName}',
999	                                  },
1000	                                  {
1001	                                    storeName: (
1002	                                      <Link
1003	                                        as="button"
1004	                                        color="blue.600"
1005	                                        textDecoration="underline"
1006	                                        onClick={onOpenStoreLocator}
1007	                                      >
1008	                                        {storeName}
1009	                                      </Link>
1010	                                    ),
1011	                                  },
1012	                                )
1013	                              : intl.formatMessage(
1014	                                  {
1015	                                    id: 'product_view.status.out_of_stock_at_store',
1016	                                    defaultMessage: 'Out of Stock at {storeName}',
1017	                                  },
1018	                                  {
1019	                                    storeName: (
1020	                                      <Link
1021	                                        as="button"
1022	                                        color="blue.600"
1023	                                        textDecoration="underline"
1024	                                        onClick={onOpenStoreLocator}
1025	                                      >
1026	                                        {storeName}
1027	                                      </Link>
1028	                                    ),
1029	                                  },
1030	                                )}
1031	                          </Text>
1032	                        )}
1033	
1034	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1035	                        {!pickupEnabled && !storeName && !inventoryId && (
1036	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1037	                            <FormattedMessage
1038	                              defaultMessage="Pick up in "
1039	                              id="product_view.label.pickup_in_select_store_prefix"
1040	                            />{' '}
1041	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1042	                              <FormattedMessage
1043	                                defaultMessage="Select Store"
1044	                                id="product_view.label.select_store_link"
1045	                              />
1046	                            </Link>
1047	                          </Text>
1048	                        )}
1049	                      </>
1050	                    )}
1051	                  </>
1052	                )}
1053	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1054	                  {renderActionButtons()}
1055	                </Box>
1056	              </Box>
1057	            </Box>
1058	          </VStack>
1059	        </Flex>
1060	
1061	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1062	        <Box
1063	          position="fixed"
1064	          bg="white"
1065	          width="100%"
1066	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1067	          p={[4, 4, 6]}
1068	          left={0}
1069	          bottom={0}
1070	          zIndex={2}
1071	          boxShadow={theme.shadows.top}
1072	        >
1073	          {renderActionButtons()}
1074	        </Box>
1075	
1076	        {/* Loading overlay during express payment confirmation */}
1077	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1078	      </Flex>
1079	    );
1080	  },
1081	);
1082	
1083	ProductView.displayName = 'ProductView';
1084	
1085	/*
1086	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1087	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1088	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1089	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1090	 */
1091	
